function categoryPage(){let c=cat(params.get('cat'));let list=ITEMS.filter(x=>x.cat===c.id);shell(`${back('services.html','كل الأقسام')}<section class="panel category-hero"><div class="ico">${c.icon}</div><div><h1>${c.ar}</h1><p class="muted">${c.desc}</p><span class="status wait">${list.length} خدمة داخل القسم</span></div></section><div class="catalog-tools"><input id="categorySearch" placeholder="ابحث باسم الخدمة أو تفاصيلها..."/><label class="checkline"><input id="categoryHot" type="checkbox"> الخدمات المميزة فقط</label><select id="categorySort"><option value="default">الترتيب الافتراضي</option><option value="az">الاسم: أ إلى ي</option></select></div><div class="grid" id="categoryGrid">${list.map(cardItem).join('')}</div><div class="notice" style="margin-top:18px">كل خدمة لها صفحة مستقلة تشمل الوصف والمتطلبات والمدة وحالة التوفر ونموذج الطلب. الأسعار الفعلية يضيفها المدير من لوحة الإدارة.</div>`);let q=$('#categorySearch'),h=$('#categoryHot'),sort=$('#categorySort');function filter(){let a=list.filter(x=>(!q.value||(x.name+' '+x.desc+' '+x.details).toLowerCase().includes(q.value.toLowerCase()))&&(!h.checked||x.hot));if(sort.value==='az')a.sort((x,y)=>x.name.localeCompare(y.name,'ar'));$('#categoryGrid').innerHTML=a.map(cardItem).join('')||'<div class="panel empty">لا توجد نتائج مطابقة.</div>';}[q,h,sort].forEach(x=>x.addEventListener('input',filter));}
function servicePage(){let s=ITEMS.find(x=>x.id===params.get('id'))||ITEMS[0],c=cat(s.cat);let related=ITEMS.filter(x=>x.cat===s.cat&&x.id!==s.id).slice(0,4);let isDevice=['imei','samsung','android','frp','mdm','icloud'].includes(s.cat);let extra=s.cat==='games'?'<div class="field"><label>Player ID</label><input name="player_id" placeholder="معرف اللاعب" required></div><div class="field"><label>الدولة / المنطقة</label><input name="region" placeholder="الدولة أو المنطقة" required></div>':s.cat==='giftcards'?'<div class="field"><label>الدولة / المنطقة</label><input name="region" placeholder="الدولة أو المنطقة" required></div><div class="field"><label>الفئة المطلوبة</label><input name="denomination" placeholder="مثال: 10 USD" required></div>':s.cat==='rentals'?'<div class="field"><label>وقت بداية الحجز</label><input name="start_time" type="datetime-local" required></div><div class="field"><label>البريد الإلكتروني</label><input name="email" type="email" placeholder="name@example.com" required></div>':s.cat==='credit'?'<div class="field"><label>اسم المستخدم لدى الأداة</label><input name="tool_user" required></div><div class="field"><label>كمية الكريدت</label><input name="quantity" type="number" min="1" required></div>':s.cat==='box'||s.cat==='server'||s.cat==='licenses'?'<div class="field"><label>اسم المستخدم / البريد لدى المزود</label><input name="provider_account" required></div><div class="field"><label>المدة أو نوع التفعيل</label><input name="term" placeholder="مثال: سنة واحدة"></div>':'<div class="field"><label>تفاصيل إضافية</label><input name="extra" placeholder="أدخل التفاصيل المطلوبة إن وجدت"></div>';shell(`${back(catLink(c),`العودة إلى ${c.ar}`)}<div class="service-detail-head"><div><span class="mini-tag">${c.ar}</span>${s.hot?'<span class="hot">HOT</span>':''}<h1>${s.name}</h1><p class="muted">${s.desc}</p></div><div class="service-price-card"><small>السعر</small><strong>${priceText(s)}</strong><span>يؤكد المدير السعر قبل الطلب</span></div></div><div class="form-grid"><section class="panel"><h2>تفاصيل الخدمة</h2><p>${s.details}</p><div class="detail-list"><div><small>مدة التنفيذ</small><b>${s.duration}</b></div><div><small>التوفر</small><b>${s.availability}</b></div><div><small>القسم</small><b>${c.ar}</b></div></div><h3>المتطلبات قبل الطلب</h3><p class="muted">${s.requirements}</p><h3>سياسة التنفيذ</h3><ul class="muted"><li>السعر النهائي والعملة يعرضهما المدير قبل اعتماد الطلب.</li><li>لا يبدأ التنفيذ إلا بعد مراجعة البيانات والتأكد من التوافق والتوفر.</li><li>خدمات الحسابات والأجهزة المقفلة تتطلب إثبات ملكية أو تفويضاً موثقاً، وتتم عبر القنوات الرسمية فقط.</li><li>لا ترسل كلمة مرورك أو رموز OTP أو بيانات بطاقتك البنكية في نموذج الطلب.</li></ul><div class="notice">الأسعار في هذه النسخة غير مدخلة بعد. سيحدد المدير سعر كل خدمة بالدولار أو الجنيه السوداني، وتُخصم القيمة المعتمدة من محفظة العميل بالدولار بعد تفعيل النظام الآمن.</div></section><section class="panel"><h2>طلب الخدمة</h2><p class="muted small">أدخل البيانات المطلوبة بدقة. سيُحفظ الطلب في قاعدة البيانات قبل أي تواصل خارجي بعد تفعيل Supabase.</p><form class="demo-form"><div class="field"><label>${isDevice?'IMEI / SN (في خانة واحدة)':'مرجع الطلب أو رقم الجهاز (إن وجد)'}</label><input name="device_ref" placeholder="${isDevice?'أدخل IMEI أو SN':'اختياري'}" ${isDevice?'required':''}></div>${isDevice?'<div class="field"><label>الشركة والطراز</label><input name="model" placeholder="مثال: Samsung SM-A..." required></div>':''}${extra}<div class="field"><label>البريد الإلكتروني</label><input name="contact_email" type="email" placeholder="name@example.com" required></div><div class="field"><label>تفاصيل الطلب</label><textarea name="details" placeholder="أي معلومات إضافية تساعد في تنفيذ الخدمة"></textarea></div>${['frp','mdm','icloud'].includes(s.cat)?'<label class="checkline"><input type="checkbox" required> أؤكد أنني مالك الجهاز أو لدي تفويض رسمي، وأوافق على التحقق من المستندات.</label>':''}<button class="btn btn-gold btn-block" type="submit">إرسال طلب الخدمة</button><p class="form-msg muted"></p></form></section></div>${related.length?`<div class="section-head"><div><h2>خدمات أخرى في نفس القسم</h2><p>تصفح الخدمات المرتبطة.</p></div><a class="btn btn-ghost" href="${catLink(c)}">كل خدمات القسم</a></div><div class="grid">${related.map(cardItem).join('')}</div>`:''}`);demoForms();}
function catalogPage(kind){let title=kind==='imei'?'خدمات IMEI والشبكات':kind==='server'?'السيرفرات والتفعيلات وBox':'خدمات الملفات';let ids=kind==='imei'?['imei','frp','mdm','icloud','samsung','android']:kind==='server'?['server','box','credit','licenses']:['files'];let arr=ITEMS.filter(x=>ids.includes(x.cat));shell(`${back('services.html','كل الأقسام')}<div class="section-head"><div><h1>${title}</h1><p>${arr.length} خدمة منفصلة — افتح أي خدمة لعرض تفاصيلها.</p></div></div><div class="catalog-tools"><input id="catalogSearch" placeholder="ابحث عن خدمة..."/><label class="checkline"><input id="hotOnly" type="checkbox"> عرض الخدمات المميزة فقط</label></div><div class="grid" id="catalogGrid">${arr.map(cardItem).join('')}</div>`);let search=$('#catalogSearch'),hot=$('#hotOnly');function filter(){let q=search.value.toLowerCase();$('#catalogGrid').innerHTML=arr.filter(x=>(!q||(x.name+x.desc).toLowerCase().includes(q))&&(!hot.checked||x.hot)).map(cardItem).join('')||'<div class="panel empty">لا توجد نتائج مطابقة.</div>';}search.addEventListener('input',filter);hot.addEventListener('change',filter);}
function reseller(){shell(`${back('index.html','الرئيسية')}<div class="section-head"><div><h1>أسعار الخدمات والموزعين</h1><p>كتالوج موحد مع بحث وتصفية وعرض السعر والمدة والتوفر.</p></div><span class="status wait">الأسعار يحددها المدير</span></div><div class="catalog-tools"><input id="priceSearch" placeholder="ابحث باسم الخدمة أو الأداة..."/><select id="catFilter"><option value="all">كل الفئات</option>${CATS.map(c=>`<option value="${c.id}">${c.ar}</option>`).join('')}</select><label class="checkline"><input type="checkbox" id="hotFilter"> الخدمات المميزة فقط</label></div><div class="table-wrap"><table><thead><tr><th>الخدمة</th><th>القسم</th><th>السعر</th><th>المدة</th><th>التوفر</th><th></th></tr></thead><tbody id="priceRows">${priceRows(PRICES)}</tbody></table></div><p class="muted small">قائمة تجريبية لتوضيح طريقة العرض. أضف كتالوجك وأسعارك الفعلية من لوحة الإدارة بعد الربط.</p>`);let q=$('#priceSearch'),f=$('#catFilter'),h=$('#hotFilter');function run(){let list=PRICES.filter(x=>(!q.value||(x.name+x.desc).toLowerCase().includes(q.value.toLowerCase()))&&(f.value==='all'||x.cat===f.value)&&(!h.checked||x.hot));$('#priceRows').innerHTML=priceRows(list)||'<tr><td colspan="6">لا توجد نتائج.</td></tr>';}[q,f,h].forEach(x=>x.addEventListener('input',run));}
function priceRows(list){return list.map(x=>`<tr><td><b>${x.name}</b><div class="muted small">${x.desc}</div></td><td>${cat(x.cat).ar}</td><td class="gold-text">${priceText(x)}</td><td>${x.duration}</td><td>${x.stock}</td><td><a class="btn btn-small btn-ghost" href="service.html?id=${x.id}">اطلب</a></td></tr>`).join('')}
function rentals(){let list=ITEMS.filter(x=>x.cat==='rentals');shell(`${back('services.html','كل الأقسام')}<div class="section-head"><div><h1>تأجير الأدوات</h1><p>${list.length} خيارات تأجير منفصلة. افتح الأداة المطلوبة لمراجعة المدة والتفاصيل.</p></div></div><div class="catalog-tools"><input id="rentalSearch" placeholder="ابحث باسم الأداة أو مدة التأجير..."/></div><div class="grid" id="rentalGrid">${list.map(cardItem).join('')}</div><div class="notice">يتم تسليم صلاحيات الأدوات المؤقتة بطريقة آمنة ووفق ترخيص المزود. لا تشارك بيانات الدخول مع أي طرف آخر.</div>`);let q=$('#rentalSearch');q.addEventListener('input',()=>{$('#rentalGrid').innerHTML=list.filter(x=>(x.name+' '+x.desc).toLowerCase().includes(q.value.toLowerCase())).map(cardItem).join('')||'<div class="panel empty">لا توجد نتائج.</div>';});}
