function auth(reg){shell(`${back('index.html','الرئيسية')}<div class="panel narrow"><h1>${reg?'إنشاء حساب':'تسجيل الدخول'}</h1><p class="muted">${reg?'أنشئ حساب عميل أو تاجر للبدء.':'ادخل إلى حسابك لمتابعة خدماتك.'}</p><form class="demo-form">${reg?'<div class="field"><label>الاسم الكامل</label><input required placeholder="الاسم"></div>':''}<div class="field"><label>البريد الإلكتروني</label><input type="email" required placeholder="name@example.com"></div>${reg?'<div class="field"><label>رقم الهاتف</label><input placeholder="رقم واتساب"></div>':''}<div class="field"><label>كلمة المرور</label><input type="password" required minlength="8" placeholder="8 أحرف على الأقل"></div>${reg?'<div class="field"><label>نوع الحساب</label><select><option>عميل</option><option>تاجر / موزع — بعد الموافقة</option></select></div>':''}<button class="btn btn-gold btn-block" type="submit">${reg?'إنشاء الحساب':'تسجيل الدخول'}</button><p class="form-msg muted"></p></form><p class="muted">${reg?'لديك حساب؟ <a href="login.html">تسجيل الدخول</a>':'ليس لديك حساب؟ <a href="register.html">إنشاء حساب جديد</a>'}</p><div class="security-box"><b>حماية الحساب</b><p>سيتم دعم التحقق بخطوتين (Authenticator / OTP) بعد تفعيل المصادقة متعددة العوامل في Supabase.</p></div></div>`);demoForms();}
