function faq(){let qs=[['كيف أفتح حساباً؟','من صفحة إنشاء الحساب، أدخل بياناتك ثم فعّل بريدك الإلكتروني.'],['كيف يتم شحن الرصيد؟','أرسل طلب الشحن مع اسم المستخدم والبريد والمبلغ، ثم تواصل مع الإدارة عبر واتساب للمراجعة.'],['كيف أتابع طلبي؟','من صفحة طلباتي أو صفحة تتبع الطلب بعد تفعيل الحساب وربط قاعدة البيانات.'],['هل الأسعار ثابتة؟','لا؛ المدير يحدد أسعار الخدمات وسعر الصرف، ويمكن أن تختلف حسب فئة الحساب.'],['هل يمكنني طلب خدمة لجهاز لا أملكه؟','الخدمات الحساسة تتطلب ملكية أو تفويضاً قانونياً واضحاً، ولا تُنفذ طلبات تجاوز الحماية أو الوصول غير المصرح به.']];shell(`${back('index.html','الرئيسية')}<h1>الأسئلة الشائعة</h1>${qs.map((q,i)=>`<details class="faq"><summary>${q[0]}</summary><p class="muted">${q[1]}</p></details>`).join('')}`)}
function admin(){
 const catOptions=CATS.map(c=>`<option value="${c.id}">${c.ar}</option>`).join('');
 const esc=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
 const rows=()=>ADMIN_SERVICES.map(x=>`<tr><td><b>${esc(x.name)}</b><div class="muted small">${esc(x.id)}</div></td><td>${esc(cat(x.cat).ar)}</td><td>${x.price==null?'يحدده المدير':esc(x.price+' '+(x.currency||'USD'))}</td><td><button class="btn btn-small btn-ghost" data-edit-service="${esc(x.id)}" type="button">تعديل</button> <button class="btn btn-small btn-red" data-delete-service="${esc(x.id)}" type="button">حذف</button></td></tr>`).join('')||'<tr><td colspan="4" class="muted">لم تضف خدمات مخصصة بعد.</td></tr>';
 shell(`${back('index.html','الرئيسية')}<div class="section-head"><div><h1>لوحة الإدارة</h1><p>إدارة كتالوج HANI SOFTWARE وإضافة خدماتك بنفسك.</p></div><span class="status wait">إدارة تجريبية محلية</span></div><div class="notice">يمكنك إضافة الخدمات وتعديلها وحذفها من هذه الصفحة. حالياً تُحفظ التغييرات في المتصفح الذي تستخدمه فقط؛ لكي تظهر لكل العملاء والأجهزة وتكون محمية بصلاحيات المدير، يجب ربط Supabase وتفعيل تسجيل دخول المدير وRLS.</div><div class="panel"><h2 id="serviceFormTitle">إضافة خدمة جديدة</h2><form id="adminServiceForm"><input type="hidden" name="edit_id"><div class="form-grid"><div class="field"><label>اسم الخدمة</label><input name="name" required placeholder="مثال: FRP HONOR KY"></div><div class="field"><label>القسم</label><select name="cat" required>${catOptions}</select></div><div class="field"><label>وصف مختصر</label><input name="desc" required placeholder="وصف يظهر في بطاقة الخدمة"></div><div class="field"><label>مدة التنفيذ</label><input name="duration" placeholder="مثال: 30 دقيقة أو حسب التوفر"></div><div class="field"><label>السعر</label><input name="price" type="number" min="0" step="0.01" placeholder="اتركه فارغاً ليحدده المدير لاحقاً"></div><div class="field"><label>العملة</label><select name="currency"><option value="USD">USD — دولار</option><option value="SDG">SDG — جنيه سوداني</option></select></div><div class="field"><label>حالة التوفر</label><input name="availability" placeholder="متاح بعد مراجعة الطلب"></div><div class="field"><label>المتطلبات</label><input name="requirements" placeholder="البيانات المطلوبة من العميل"></div></div><div class="field"><label>تفاصيل الخدمة</label><textarea name="details" placeholder="اشرح الخدمة وشروطها والأجهزة المدعومة"></textarea></div><label class="checkline"><input type="checkbox" name="hot"> خدمة مميزة (HOT)</label><div class="actions"><button class="btn btn-gold" type="submit">حفظ الخدمة</button><button class="btn btn-ghost" type="button" id="cancelServiceEdit" hidden>إلغاء التعديل</button></div><p class="form-msg muted" id="adminServiceMsg"></p></form></div><div class="panel"><div class="section-head"><div><h2>خدماتك التي أضفتها</h2><p>${ADMIN_SERVICES.length} خدمة مخصصة محفوظة في هذا المتصفح.</p></div></div><div class="table-wrap"><table><thead><tr><th>الخدمة</th><th>القسم</th><th>السعر</th><th>الإجراءات</th></tr></thead><tbody id="adminServiceRows">${rows()}</tbody></table></div></div><div class="panel"><h2>إعدادات العملة</h2><p class="muted">المحفظة بالدولار USD. الخدمات المسعرة بالجنيه تُحوّل حسب سعر الصرف الذي يحدده المدير، ويحفظ النظام سعر الصرف التاريخي لكل طلب بعد تنفيذ الربط الآمن.</p></div>`);
 const form=$('#adminServiceForm'),msg=$('#adminServiceMsg');
 const persist=()=>{localStorage.setItem(ADMIN_SERVICES_KEY,JSON.stringify(ADMIN_SERVICES));};
 const reset=()=>{form.reset();form.elements.edit_id.value='';$('#serviceFormTitle').textContent='إضافة خدمة جديدة';$('#cancelServiceEdit').hidden=true;};
 form.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form);const name=String(d.get('name')||'').trim();if(!name){msg.textContent='اكتب اسم الخدمة أولاً.';return;}let id=String(d.get('edit_id')||'');if(!id){id='custom-'+name.toLowerCase().replace(/[^a-z0-9\u0600-\u06ff]+/g,'-').replace(/^-|-$/g,'')+'-'+Date.now().toString(36);}const itemData={id,cat:String(d.get('cat')),name,desc:String(d.get('desc')||''),details:String(d.get('details')||d.get('desc')||''),requirements:String(d.get('requirements')||'يحدد المدير متطلبات الخدمة قبل قبول الطلب.'),duration:String(d.get('duration')||'يحدد بعد مراجعة الطلب'),availability:String(d.get('availability')||'حسب التوفر ومراجعة الإدارة'),hot:d.get('hot')==='on',price:d.get('price')===''?null:Number(d.get('price')),currency:String(d.get('currency')||'USD'),stock:String(d.get('availability')||'حسب التوفر ومراجعة الإدارة')};const idx=ADMIN_SERVICES.findIndex(x=>x.id===id);if(idx>=0)ADMIN_SERVICES[idx]=itemData;else ADMIN_SERVICES.push(itemData);persist();msg.textContent=idx>=0?'تم تحديث الخدمة في هذا المتصفح.':'تمت إضافة الخدمة في هذا المتصفح.';reset();$('#adminServiceRows').innerHTML=rows();location.reload();});
 $('#cancelServiceEdit').addEventListener('click',reset);
 $('#adminServiceRows').addEventListener('click',e=>{const edit=e.target.closest('[data-edit-service]');const del=e.target.closest('[data-delete-service]');if(edit){const x=ADMIN_SERVICES.find(v=>v.id===edit.dataset.editService);if(!x)return;form.elements.edit_id.value=x.id;form.elements.name.value=x.name;form.elements.cat.value=x.cat;form.elements.desc.value=x.desc;form.elements.details.value=x.details;form.elements.requirements.value=x.requirements;form.elements.duration.value=x.duration;form.elements.availability.value=x.availability;form.elements.price.value=x.price??'';form.elements.currency.value=x.currency||'USD';form.elements.hot.checked=!!x.hot;$('#serviceFormTitle').textContent='تعديل الخدمة';$('#cancelServiceEdit').hidden=false;window.scrollTo({top:0,behavior:'smooth'});}else if(del){const id=del.dataset.deleteService;const x=ADMIN_SERVICES.find(v=>v.id===id);if(!x||!confirm(`هل تريد حذف الخدمة: ${x.name}؟`))return;ADMIN_SERVICES=ADMIN_SERVICES.filter(v=>v.id!==id);persist();location.reload();}});
}
function demoForms(){$$('.demo-form').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();let m=f.querySelector('.form-msg');if(m)m.textContent='تم التحقق من النموذج في المعاينة فقط. لم يتم حفظ بيانات أو تنفيذ عملية مالية. يلزم ربط Supabase أولاً.';}));}
